package com.example

/**
 * High-quality, 100% curriculum-accurate Question Bank for Buddhism (බුද්ධ ධර්මය)
 * Covers 10 distinct syllabus lessons with 10 unique MCQs per set (100 total distinct questions).
 */
object QuizBankBuddhism {

  fun getQuestion(
    grade: String,
    setIdx: Int,
    qIdx: Int,
    qNumber: Int,
    topic: String
  ): QuizQuestion {
    return when (setIdx) {
      // SET 1: සිද්ධාර්ථ කුමාරෝත්පත්තිය හා බෝසත් චරිතය
      1 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "සිද්ධාර්ථ බෝසතාණන් වහන්සේ මෙලොව උපත ලැබුවේ කුමන ස්ථානයේදීද?", listOf("බුද්ධගයාවේදී", "ලුම්බිණි සල් උයනේදී", "කුසිනාරාවේදී", "ඉසිපතනයේදී"), 1, "ලුම්බිණි සල් උයනේදී වෙසක් පුන් පොහෝ දින මායා දේවියගේ කුසින් බෝසත් කුමරු උපත ලැබීය.")
        2 -> QuizQuestion(qNumber, "සිද්ධාර්ථ කුමාරයාගේ පියාණන් සහ මෑණියන් කවුරුන්ද?", listOf("සුදොවුන් රජු සහ මහාමායා දේවිය", "බිම්බිසාර රජු සහ ඛේමා දේවිය", "කොසොල් රජු සහ මල්ලිකා දේවිය", "අජාසත් රජු"), 0, "කපිලවස්තු පුර ශාක්‍ය වංශික සුද්ධෝදන රජු සහ මහාමායා රැජින බෝසතුන්ගේ දෙමව්පියෝ වූහ.")
        3 -> QuizQuestion(qNumber, "උපතින් පසු කුමරු දැක 'මොහු ඒකාන්තයෙන්ම බුදුවන්නේය' යැයි එක් ඇඟිල්ලක් ඔසවා පැවසූ තරුණ බමුණා කවුද?", listOf("කොණ්ඩඤ්ඤ බමුණා", "අසිත (කාලදේවල) තවුසා", "රාම", "උද්දක"), 0, "අටක් වූ බමුණන් අතුරින් බාලම බමුණා වූ කොණ්ඩඤ්ඤ බමුණා ඒකාන්තයෙන්ම බුදුවන බව පැවසීය.")
        4 -> QuizQuestion(qNumber, "කුමරු ගිහිගෙය කලකිරීමට හේතු වූ 'සතර පෙර නිමිති' මොනවාද?", listOf("මහල්ලා, ලෙඩා, මළමිනිය සහ පැවිදි රුව", "හිරු, සඳු, තරු, අහස", "ගින්න, ජලය, සුළඟ, පෘථිවිය", "දුප්පතා, පොහොසතා, රජු, සෙබළා"), 0, "උයන් කෙළියට යන අතරමගදී දුටු මෙම නිමිති සසරේ යථාර්ථය වැටහෙන්නට මඟ පෑදීය.")
        5 -> QuizQuestion(qNumber, "සිද්ධාර්ථ කුමාරයා මහාභිනිෂ්ක්‍රමණය කළේ කුමන පුන් පොහෝ දිනයකදීද?", listOf("වෙසක් පොහෝ දින", "ඇසළ පුන් පොහෝ දින", "පොසොන් පොහෝ දින", "ඉල් පොහෝ දින"), 1, "රාහුල කුමරු උපන් ඇසළ පුන් පොහෝ දින කන්ථක අසු පිට නැගී අනෝමා ගං තෙරට වැඩම කළේය.")
        6 -> QuizQuestion(qNumber, "අනෝමා ගං තෙරදී බෝසතාණන් වහන්සේට අටපිරිකර පූජා කළේ කවුරුන්ද?", listOf("ඝටීකාර මහා බ්‍රහ්මයා", "සක් දෙවිඳු", "චන්න ඇමති", "සුජාතාව"), 0, "ඝටීකාර බ්‍රහ්මයා විසින් අහසින් පැමිණ බෝසතුන්ට අටපිරිකර පූජා කළ බව සඳහන් වේ.")
        7 -> QuizQuestion(qNumber, "බෝසතුන් මුලින්ම ගොස් සමාපත්ති උපදවා ගත් ප්‍රථම ගුරුවරයා කවුද?", listOf("ආලාරකාලාම තවුසා", "උද්දකරාමපුත්ත", "සංජය පිරිවැජියා", "කොණ්ඩඤ්ඤ"), 0, "ආලාරකාලාම වෙතින් ආකිඤ්චඤ්ඤායතන සමාපත්තිය ද, උද්දකරාමපුත්ත වෙතින් නේවසඤ්ඤානාසඤ්ඤායතන සමාපත්තිය ද ලැබූහ.")
        8 -> QuizQuestion(qNumber, "බුද්ධත්වය ලැබීමට පෙර බෝසතුන් වසර 6ක් පුරා කළ දැඩි ශරීර දුක් දීමේ තපස කුමක්ද?", listOf("දුෂ්කරක්‍රියාව (කාමසුඛල්ලිකානුයෝගය නොවේ)", "සීල ව්‍රතය", "අත්තකිලමථානුයෝගය", "උපවාසය පමණි"), 0, "අන්ත දෙකෙන් එකක් වූ අත්තකිලමථානුයෝගී දුෂ්කරක්‍රියාවෙන් නිවන් දැකිය නොහැකි බව පසුව වටහා ගත්හ.")
        9 -> QuizQuestion(qNumber, "බුදුවීමට පෙර දින බෝසතුන්ට කිරිපිඬු දානය පූජා කළ සැදැහැති කුල කාන්තාව කවුද?", listOf("විශාඛාව", "සුජාතා සිටු දේවිය", "අම්බපාලිය", "පටාචාරාව"), 1, "සේනානි නිගමයේ සුජාතා සිටු දියණිය අජපල් නුගරුක මුලදී රන් තලියක කිරිපිඬු පූජා කළාය.")
        else -> QuizQuestion(qNumber, "බෝසතුන් 'මම බුදු වී මිස මෙම ආසනයෙන් නොනැගිටිමි' යි අධිෂ්ඨාන කර හිඳගත් ආසනය කුමක්ද?", listOf("වජ්‍රාසනය (අපරාජිත පර්යංකය)", "රත්න ආසනය", "සිංහාසනය", "පද්මාසනය"), 0, "බුද්ධගයාවේ ශ්‍රී මහා බෝධි මූලයේ පිහිටි වජ්‍රාසනයේ වැඩහිඳ චතුරංග සමන්නාගත වීර්යයෙන් බුද්ධත්වයට පත්වූ සේක.")
      }

      // SET 2: බුද්ධත්වය හා ප්‍රථම ධර්ම දේශනාව
      2 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "සිද්ධාර්ථ ගෞතමයන් වහන්සේ සියලු කෙලෙසුන් නසා සම්මා සම්බුද්ධත්වයට පත් වූයේ කුමන පුන් පොහෝ දිනයකද?", listOf("ඇසළ පොහෝ දින", "වෙසක් පුන් පොහෝ දින", "පොසොන් පොහෝ දින", "දුරුතු පොහෝ දින"), 1, "වයස අවුරුදු 35 දී වෙසක් පුන් පොහෝ දින අලුයම ලොව්තුරා සම්බුද්ධත්වයට පත් වූ සේක.")
        2 -> QuizQuestion(qNumber, "බුද්ධත්වයෙන් පසු බුදුරජාණන් වහන්සේ ගුරු ගෞරවය දැක්වීම සඳහා කළ ප්‍රථම ක්‍රියාව කුමක්ද?", listOf("අනිමිසලෝචන පූජාවෙන් බෝධිය දෙස බලා සිටීම", "දම් දෙසුම", "රජගහනුවරට වැඩමවීම", "නැවත නිවසට යාම"), 0, "තමන්ට සෙවණ දුන් ශ්‍රී මහා බෝධීන් වහන්සේ දෙස ඇසිපිය නොහෙළා සතියක් බලා සිටිමින් කෘතගුණ සැලකීමේ උතුම් ආදර්ශය දුන් සේක.")
